1: /* ==========================================================================
2:    CAR VAULT — Shared UI, Navigation, Wishlist & 4-State Booking Flow (js/common.js)
3:    ========================================================================== */
4: 
5: const PATH_PREFIX = document.body.dataset.prefix || "";
6: const CURRENT_PAGE = document.body.dataset.page || "home";
7: const WISHLIST_STORAGE_KEY = "carvault_wishlist";
8: const BOOKINGS_STORAGE_KEY = "carvault_bookings";
9: 
10: /* ---------- Helper Functions ---------- */
11: function getCarById(carId) {
12:   return CAR_VAULT_CARS.find((car) => car.id === carId) || CAR_VAULT_CARS.find((car) => car.id === "honda-civic") || CAR_VAULT_CARS[0];
13: }
14: 
15: function getWishlist() {
16:   try {
17:     const saved = JSON.parse(localStorage.getItem(WISHLIST_STORAGE_KEY));
18:     return Array.isArray(saved) ? saved : [];
19:   } catch (error) {
20:     return [];
21:   }
22: }
23: 
24: function saveWishlist(list) {
25:   localStorage.setItem(WISHLIST_STORAGE_KEY, JSON.stringify(list));
26: }
27: 
28: function isInWishlist(carId) {
29:   return getWishlist().includes(carId);
30: }
31: 
32: function toggleWishlistItem(carId) {
33:   const list = getWishlist();
34:   const exists = list.includes(carId);
35:   const updated = exists ? list.filter((id) => id !== carId) : [...list, carId];
36:   saveWishlist(updated);
37:   updateSavedBadges();
38:   showToast(exists ? "Removed from Wishlist" : "Saved to Wishlist");
39:   return !exists;
40: }
41: 
42: function getBookings() {
43:   try {
44:     const saved = JSON.parse(localStorage.getItem(BOOKINGS_STORAGE_KEY));
45:     return Array.isArray(saved) ? saved : [];
46:   } catch (error) {
47:     return [];
48:   }
49: }
50: 
51: function showToast(message) {
52:   const existing = document.querySelector(".toast");
53:   if (existing) {
54:     existing.remove();
55:   }
56:   const toast = document.createElement("div");
57:   toast.className = "toast";
58:   toast.textContent = message;
59:   document.body.appendChild(toast);
60:   setTimeout(() => {
61:     toast.remove();
62:   }, 2600);
63: }
64: 
65: /* ---------- Shared Car Card Renderer ---------- */
66: function buildCarCardHtml(car) {
67:   const detailsUrl = `${PATH_PREFIX}pages/car-details.html?id=${encodeURIComponent(car.id)}`;
68:   const saved = isInWishlist(car.id);
69: 
70:   return `
71:     <article class="car-card">
72:       <a href="${detailsUrl}" class="car-card-link">
73:         <div class="car-card-image-wrap">
74:           <img src="${PATH_PREFIX}${car.image}" alt="${car.year} ${car.model}" loading="lazy">
75:           <span class="car-badge">${car.condition}</span>
76:         </div>
77:         <div class="car-card-body">
78:           <div class="car-card-meta">${car.brand} &middot; ${car.type}</div>
79:           <h3 class="car-card-title">${car.model}</h3>
80:           <div class="car-card-price">${car.priceLabel}</div>
81:         </div>
82:       </a>
83:       <div class="car-card-footer">
84:         <a href="${detailsUrl}" class="card-details-cta">View Details &rarr;</a>
85:         <button
86:           type="button"
87:           class="icon-wish-btn ${saved ? "saved" : ""}"
88:           data-wish-id="${car.id}"
89:           aria-label="Toggle wishlist for ${car.model}"
90:         >
91:           ${saved ? "&#9829; Saved" : "&#9825; Save"}
92:         </button>
93:       </div>
94:     </article>
95:   `;
96: }
