450: function handleBookingSubmit(event) {
451:   event.preventDefault();
452:   const form = event.target;
453: 
454:   // Save State 2 (Filled Form) values so "Try Again" keeps what the user typed
455:   currentBookingDraft = {
456:     carId: form.carId.value,
457:     name: form.name.value.trim(),
458:     phone: form.phone.value.trim(),
459:     email: form.email.value.trim(),
460:     date: form.date.value,
461:     time: form.time.value
462:   };
463: 
464:   const hasRequiredBasics =
465:     currentBookingDraft.name.length >= 2 &&
466:     Boolean(currentBookingDraft.date) &&
467:     Boolean(currentBookingDraft.time);
468: 
469:   // State 4: Failed Validation (matching paper prototype State 4)
470:   if (!hasRequiredBasics || !validatePhoneAndEmail(currentBookingDraft.phone, currentBookingDraft.email)) {
471:     renderBookingFailedState();
472:     return;
473:   }
474: 
475:   // State 3: Success
476:   const selectedCar = getCarById(currentBookingDraft.carId);
477:   const savedBookings = getBookings();
478:   savedBookings.push({
479:     ...currentBookingDraft,
480:     carModel: selectedCar.model,
481:     createdAt: new Date().toISOString()
482:   });
483:   localStorage.setItem(BOOKINGS_STORAGE_KEY, JSON.stringify(savedBookings));
484: 
485:   renderBookingSuccessState(selectedCar, currentBookingDraft);
486: }
